package com.sanctuarygames.createtransit.elevator.client;
import java.util.*;import java.util.function.Consumer;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.*;import net.minecraft.network.chat.Component;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.item.*;
/** Client selection only: the controller still validates permissions and the block ID. */
public final class MaterialPickerScreen extends Screen {
 private boolean defaultFloor;private final ItemStack current;private final Screen parent;private final Consumer<String> selected;private EditBox search;private int page;private List<ItemStack> blocks=List.of();
 public MaterialPickerScreen(Screen parent,String currentId,Consumer<String> selected){super(com.sanctuarygames.createtransit.TransitText.uiText("Choose block material"));this.parent=parent;this.selected=selected;defaultFloor=currentId.equals("createtransit:default_cabin_floor");var id=net.minecraft.resources.ResourceLocation.tryParse(defaultFloor?"minecraft:polished_deepslate":currentId);current=id==null?ItemStack.EMPTY:new ItemStack(BuiltInRegistries.BLOCK.get(id));}
 @Override protected void init(){search=new EditBox(font,12,28,width-24,20,com.sanctuarygames.createtransit.TransitText.uiText("Search blocks"));addRenderableWidget(search);search.setResponder(v->{page=0;refresh();});refresh();}
 private void refresh(){var list=new ArrayList<ItemStack>();String q=search.getValue().toLowerCase(Locale.ROOT);if(minecraft.player!=null){for(int i=0;i<36;i++){var s=minecraft.player.getInventory().getItem(i);if(s.getItem() instanceof BlockItem&&(s.getHoverName().getString().toLowerCase(Locale.ROOT).contains(q)))list.add(s.copy());}if(minecraft.player.isCreative())for(var b:BuiltInRegistries.BLOCK){var s=new ItemStack(b);if(s.getItem() instanceof BlockItem&&(BuiltInRegistries.BLOCK.getKey(b).toString().contains(q)||s.getHoverName().getString().toLowerCase(Locale.ROOT).contains(q)))list.add(s);}}blocks=List.copyOf(list);layout();}
 private int cols(){return Math.max(1,(width-24)/34);}private int rows(){return Math.max(1,(height-92)/32);}
 private void layout(){var keep=search;clearWidgets();addRenderableWidget(keep);int count=cols()*rows();page=Math.clamp(page,0,Math.max(0,(blocks.size()-1)/count));for(int i=0;i<count&&page*count+i<blocks.size();i++){var s=blocks.get(page*count+i);int x=12+i%cols()*34,y=56+i/cols()*32;var button=addRenderableWidget(StationUi.button(x,y,30,28,"",b->{minecraft.setScreen(parent);selected.accept(BuiltInRegistries.BLOCK.getKey(((BlockItem)s.getItem()).getBlock()).toString());}));button.setTooltip(Tooltip.create(s.getHoverName()));}addRenderableWidget(StationUi.button(12,height-28,50,20,"Back",b->onClose()));addRenderableWidget(StationUi.button(width-120,height-28,50,20,"Prev",b->{page--;layout();}));addRenderableWidget(StationUi.button(width-64,height-28,50,20,"Next",b->{page++;layout();}));}
 @Override public boolean mouseScrolled(double x,double y,double h,double v){page+=v<0?1:-1;layout();return true;}
 @Override public void onClose(){minecraft.setScreen(parent);}
 @Override public boolean isPauseScreen(){return false;}
 @Override public void render(GuiGraphics g,int x,int y,float p){g.fill(0,0,width,height,StationUi.themeSurface(0xff122333,.18f));g.fill(12,23,width-12,25,StationUi.accent());super.render(g,x,y,p);g.drawString(font,font.plainSubstrByWidth("Current: "+(defaultFloor?"Cabin checker floor":current.getHoverName().getString()),width-54),12,10,0xffd3f4fa);g.renderItem(current,width-28,5);if(x>=width-30&&y<24)g.renderTooltip(font,current.getHoverName(),x,y);int count=cols()*rows();for(int i=0;i<count&&page*count+i<blocks.size();i++)g.renderItem(blocks.get(page*count+i),19+i%cols()*34,62+i/cols()*32);}
}
